SELECT order_status, COUNT(DISTINCT order_id) AS siparis_sayisi
FROM orders
GROUP BY order_status;

SELECT 100.0 * AVG(CASE WHEN order_delivered_customer_date > order_estimated_delivery_date THEN 1 ELSE 0 END) AS yuzde
FROM orders
WHERE order_status = 'delivered';

SELECT COUNT(*) AS siparis
FROM orders
WHERE order_purchase_timestamp >= '2018-09-01' AND order_purchase_timestamp < '2018-10-01';

SELECT COUNT(DISTINCT p.product_category_name) AS urun_kategori_sayisi
FROM products p
JOIN product_category_name_translation t USING (product_category_name);
